export const practicalRateTasks=[
{id:'plan',title:'Plan a fair comparison',prompt:'Compare acid concentrations using equal magnesium pieces and excess acid. Choose a measurable hypothesis and controlled conditions.',fields:[['hypothesis','Prediction',[['faster','Concentration up: faster early gas formation'],['yield','Concentration up: always more final gas'],['none','No measurable prediction']],'faster'],['controls','Keep constant',[['fixed','Metal mass/surface, volume and temperature'],['vary','Change metal mass at the same time'],['rate','Force measured rate to stay constant']],'fixed']]},
{id:'gas',title:'Compare the gas records',prompt:'Both trials use equal limiting magnesium and excess acid. At20 s: A has24 cm³, B has40 cm³. Both finish at60 cm³. Calculate each start-to20 s mean and interpret the final amounts.'},
{id:'turbidity',title:'Prepare the comparison',prompt:'Use20 cm³ of40 g/dm³ thiosulfate stock. Add water to50 cm³ before the same acid addition. Endpoint times: dilute trial80 s; stock trial40 s. Keep total volume, depth and endpoint criteria comparable.'},
{id:'evaluate',title:'Improve the evidence',prompt:'A gas trial has a suspected leak, and different observers disagree on when the cross disappears.',fields:[['gasfix','Gas-method improvement',[['seal','Check seals and consistent starting'],['ignore','Ignore early gas loss'],['open','Leave delivery connections loose']],'seal'],['endpoint','Endpoint improvement',[['consistent','Same setup/observer; repeat trials'],['depth','Change liquid depth each time'],['fastest','Report only the fastest reading']],'consistent']]}
];
export function dilutedConcentration(stock,aliquot,total){if(![stock,aliquot,total].every(Number.isFinite)||stock<0||aliquot<0||total<=0||aliquot>total)throw Error('Invalid dilution');return stock*aliquot/total;}
const near=(v,n)=>String(v??'').trim()!==''&&Number.isFinite(Number(v))&&Math.abs(Number(v)-n)<=.001;
export function practicalRateCorrect(t,a){if(t.id==='gas')return near(a.rateA,1.2)&&near(a.rateB,2)&&a.final==='same';if(t.id==='turbidity')return near(a.water,30)&&near(a.concentration,16)&&a.faster==='stock';return t.fields.every(([id,,,key])=>a[id]===key);}
